<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'; import AppLayout from '../components/layout/AppLayout.vue'; import ReportNav from '../components/reports/ReportNav.vue'; import SummaryCards from '../components/reports/SummaryCards.vue'; import BarChart from '../components/reports/BarChart.vue'; import LoadingState from '../components/ui/LoadingState.vue'; import BaseButton from '../components/ui/BaseButton.vue'; import { monthlyReport, downloadExport } from '../services/reports'; import { apiErrorMessage } from '../services/api'; import type { MonthlyReport } from '../types';
const period = ref(new Date().toISOString().slice(0, 7)); const report = ref<MonthlyReport | null>(null); const loading = ref(true); const error = ref('');
async function load(): Promise<void> { loading.value = true; error.value = ''; const [year, month] = period.value.split('-').map(Number); try { report.value = await monthlyReport(year, month); } catch (e) { error.value = apiErrorMessage(e); } finally { loading.value = false; } }
async function exportFile(type: 'xlsx' | 'pdf'): Promise<void> { const [year, month] = period.value.split('-').map(Number); await downloadExport(`/exports/monthly.${type}`, { year, month }, `monthly-${period.value}.${type}`); }
watch(period, load); onMounted(load);
</script>
<template><AppLayout><div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-medium text-brand-700">Reports</p><h1 class="mt-1 text-3xl font-semibold">Monthly report</h1></div><ReportNav /></div><section class="card mt-6 flex flex-wrap items-end gap-3"><label><span class="label">Month</span><input v-model="period" class="field" type="month" /></label><BaseButton variant="secondary" @click="exportFile('xlsx')">Export Excel</BaseButton><BaseButton variant="secondary" @click="exportFile('pdf')">Export PDF</BaseButton></section><p v-if="error" class="mt-5 rounded-lg bg-red-50 p-3 text-red-700">{{ error }}</p><LoadingState v-if="loading" label="Loading report…" /><template v-else-if="report"><div class="mt-6"><SummaryCards :summary="report" /></div><section class="card mt-6"><h2 class="font-semibold">Category breakdown</h2><BarChart class="mt-5" :items="report.categories.map(c => ({ label: c.name, total: c.total }))" /><p v-if="!report.categories.length" class="mt-4 text-sm text-slate-500">No expenses in this period.</p></section></template></AppLayout></template>
